30		ticker := time.NewTicker(runnerInterval)
31		defer ticker.Stop()
32	
33		for {
34			select {
35			case <-ticker.C:
36				r.RunOnce(ctx)
37			case <-ctx.Done():
38				return
39			}
40		}
41	}
